props.pageLoadAction:
(
  /* Skip pick scan when loading screen from Create Pick */
  $exists($metadata.urlParameters.number) ? 
  (
    $payload :=  {
        "REQUEST": {
          "scannedBarcode": $metadata.urlParameters.number
        },
        "ACTION": "scanPick"
      };
    $components.Action2.fn.execute($payload);
  )
  :
  (
      /* If no urlParameters.number then look for querystring.number to see if it exists */
      $exists($metadata.querystring.number) ? 
      (
        $payload :=  {
            "REQUEST": {
              "scannedBarcode": $metadata.querystring.number
            },
            "ACTION": "scanPick"
          };
        $components.Action2.fn.execute($payload);
      )
      :
      /* If no number found, default to start up screen */
      (
       $components.Screen.fn.setContextValue("mode", "scanPick")
      )
  )
)

props.onChange:
(
  /* If this is a new value, execute the flow with the screen mode as the action param */
  $isNotNilOrEmpty(newValue) and $not(oldValue = newValue)? (
    $payload :=  {
        "REQUEST": {
          "scannedBarcode": newValue
        },
        "ACTION": $components.Screen.context.mode
      };
    $components.Action2.fn.execute($payload);
  )
)

dataSubscription.valueTransform:
(
  $affectedId := event.body.value.after.affectedPickStepId;
  $causedId := event.body.value.after.causePickStepId;

  /* Grab offending pick number for easy identification */
  $result:= $query(
  {
    "statement":'query NonConformance($where: NonConformanceWhereInput, $orderBy: [NonConformanceOrderByInput!], $first: Int, $after: String) {
      nonConformance(where: $where, orderBy: $orderBy, first: $first, after: $after) {
      edges {
        node {
          causePickStep {
            pick {
              id
              number
            }
          }
        }
      }
    }
  }',
  "variables":{
    "where":{
      "_and": [
        {
          "causePickStepId": {
            "_eq": $causedId
          } 
        },
        {
          "affectedPickStepId": {
            "_eq": $affectedId
          } 
        }
      ]
    }
  }}).nonConformance.edges[0].node.causePickStep.pick;


  {
    "affectedId": $affectedId,
    "causedById": $causedId,
    "invalidated": $affectedId in [$components.Screen.context.stops.id] ? true, 
    "problemPickNumber": $result.number,
    "message": "This pick may not have enough inventory due to Pick " & $result.number
  }


)

style.__transform:
(
  /* Highlight this card if it matches the scanned SN */
  $exists($components.Form3.data.invalidated) ?
  {
    "background-color": "#bf4e3f"
  }
)

